mapper.select:
SELECT s.user_id AS id, s.display_name AS name, () AS active, s.created_at FROM enterprise_member s JOIN app_user u ON u.id = s.user_id WHERE s.enterprise_id = #{enterprise} AND LOCATE(#{query}, s.display_name) > 0 AND
AND EXISTS (SELECT 1 FROM sys_user_role ur JOIN sys_role role_value ON role_value.enterprise_id = ur.enterprise_id AND role_value.id = ur.role_id JOIN sys_role_permission rp ON rp.enterprise_id = role_value.enterprise_id AND rp.role_id = role_value.id WHERE ur.enterprise_id = s.enterprise_id AND ur.user_id = s.user_id AND role_value.status = 'active' AND role_value.deleted_at IS NULL AND rp.permission_code = #{ownerPermission})
AND s.user_id IN #{id}
AND (s.created_at < #{cursor.time} OR (s.created_at = #{cursor.time} AND s.user_id < #{cursor.id}))
ORDER BY s.created_at DESC, s.user_id DESC LIMIT #{limit}
